function nodenoStudioHashtags(array $keywords,string $platform):array {
 $limit=$platform==='x'?1:($platform==='pinterest'?0:3);$tags=[];
 foreach(array_slice($keywords,0,$limit)as $word){$tag=preg_replace('/[^\p{L}\p{N}_]+/u','_',trim($word));if($tag!=='')$tags[]='#'.$tag;}
 return $tags;
}

function nodenoStudioSegment(array $p):string {
 $name=(string)($p['name']['tr']??'');$type=$p['productType']??'';
 $whole=(bool)preg_match('/dolap|gardırop|masa|sehpa|kitaplık|şifonyer|komodin|karyola|baza|koltuk|sandalye|portmanto|konsol|puf|tv ünitesi|kahve[\s-]*(?:köş|istasyon)/iu',$name);
 $component=(bool)preg_match('/aplik|rozet|çıta|profil|menteşe|kulp|hazeran|oyma|mobilya ayağı|masa ayağı|sehpa ayağı|ayak takımı|üst modül|elbise askısı|gardırop kapağı|dolap kapağı|kapak takımı|mobilya kapak|kapı kanadı/iu',$name);
 $raw=(bool)preg_match('/\bham\b|boyanabilir|boyasız|unpainted|unfinished/iu',$name);
 if($whole&&$raw&&!$component)return 'diy';
 if($type===''&&$whole&&!$component&&!$raw)return 'finished';
 if(($p['marketingAudience']??'')==='finished-home'&&$whole&&!$component&&!$raw)return 'finished';
 return 'trade';
}

function nodenoStudioTopic(array $p):string {
 $name=(string)($p['name']['tr']??'');$categories=implode(' ',$p['categoryIds']??[]);
 if(preg_match('/kahve[\s-]*(?:köş|istasyon|dolab|ünite)/iu',$name))return 'coffee';
 if(preg_match('/cocuk|genc/iu',$categories))return 'kids';
 if(preg_match('/çalışma|oyuncu|ofis masa/iu',$name))return 'work';
 if(preg_match('/ayakkabı|portmanto/iu',$name))return 'entry';
 if(preg_match('/dolap|gardırop|kitaplık|şifonyer|komodin/iu',$name))return 'storage';
 return 'living';
}

