function nodenoStudioFactsHash(array $p):string {
 $fields=[(string)$p['id']];foreach(['tr','en','ru','ar'] as $locale){$fields[]=(string)($p['name'][$locale]??'');$fields[]=(string)($p['modelName'][$locale]??'');}
 foreach($p['specs']??[] as $spec)foreach(['tr','en','ru','ar'] as $locale){$fields[]=(string)($spec['label'][$locale]??'');$fields[]=(string)($spec['value'][$locale]??'');}return hash('sha256',implode("\n",$fields));
}

function nodenoStudioCreativeProfile(array $p):?array {
 $profile=nodenoStudioCreativeProfiles()[$p['id']]??null;if(!$profile||!hash_equals($profile['factsSha256'],nodenoStudioFactsHash($p)))return null;return $profile;
}

function nodenoStudioLegacyCaption(array $p,string $locale,string $platform):string {
 $name=nodenoStudioName($p,$locale);$link=nodenoStudioLink($p['id'],$locale,$platform);$description=nodenoStudioProductCopy($p,$locale);
 $tags=['tr'=>'#NODENO #Mobilya #EvDekorasyonu','en'=>'#NODENO #Furniture #InteriorDesign','ru'=>'#NODENO #Мебель #Интерьер','ar'=>'#NODENO #أثاث #ديكور'];
 $caption=$name.($description!==''?"\n\n".$description:'')."\n\n".$link."\n\n".$tags[$locale];
 if($platform==='x'){$caption=nodenoStudioSlice($name,80)."\n".$link;if($description!==''&&nodenoStudioLength($caption."\n".$description)<=280)$caption=nodenoStudioSlice($name,80)."\n".$description."\n".$link;}
 if($platform==='linkedin')$caption=$name.($description!==''?"\n\n".$description:'')."\n\n".$link;return $caption;
}

function nodenoStudioRetireOldCampaign(PDO $db,?array $catalog=null):int {
 $retire=nodenoControlSetting($db,'social:creative-policy')!==NODENO_SOCIAL_CREATIVE_VERSION;
 return nodenoControlTransaction($db,static function()use($db,$catalog,$retire):int{
  $retired=0;$revised=0;
  if($retire){$q=$db->prepare("UPDATE social_posts SET status='cancelled',reason='creative_campaign_replaced',version=version+1,updated_at=? WHERE substr(id,1,5)='auto_' AND status IN ('draft','ready','blocked','scheduled') AND attempts=0 AND remote_id IS NULL AND lease_token IS NULL");$q->execute([time()]);$retired=$q->rowCount();nodenoControlSetSetting($db,'social:creative-policy',NODENO_SOCIAL_CREATIVE_VERSION);}
  if($catalog){
   $rows=$db->query("SELECT * FROM social_posts WHERE substr(id,1,5)<>'auto_' AND status IN ('draft','ready','blocked','scheduled') AND attempts=0 AND remote_id IS NULL AND lease_token IS NULL")->fetchAll();
   foreach($rows as $row){$old=json_decode($row['payload_json'],true);if(($old['creativeVersion']??'')===NODENO_SOCIAL_CREATIVE_VERSION)continue;
    // A remote video job must be reconciled, never silently replaced or billed twice.
    if(!empty($old['renderId']))continue;
    try{$p=nodenoStudioProduct($catalog,$row['product_id']);}catch(Throwable $e){continue;}
    $fresh=nodenoStudioCaption($p,$row['locale'],$row['platform'],(int)($old['angle']??0));
    $baseline=$old['generatedCaption']??nodenoStudioLegacyCaption($p,$row['locale'],$row['platform']);$edited=($old['copyEdited']??false)||isset($old['caption'])&&$old['caption']!==$baseline;
    if($edited){$fresh['caption']=$old['caption'];$fresh['copyEdited']=true;}
    if(isset($old['title'])&&$old['title']!==nodenoStudioSlice(nodenoStudioName($p,$row['locale']),$row['platform']==='youtube'?90:100))$fresh['title']=$old['title'];
    $fresh['musicId']=$old['musicId']??null;if($row['status']==='scheduled')$fresh['resumeScheduled']=true;
    $db->prepare("UPDATE social_posts SET payload_json=?,status='draft',reason='',version=version+1,updated_at=? WHERE id=? AND version=?")->execute([json_encode($fresh,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),time(),$row['id'],$row['version']]);$revised++;
   }
  }
  if($retired||$revised)nodenoStudioEvent($db,'campaign_refreshed',null,['retired'=>$retired,'revisedManual'=>$revised,'audience'=>'finished-home','creativeVersion'=>NODENO_SOCIAL_CREATIVE_VERSION]);return $retired;
 });
}
